def prog_L29H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with mild distance attenuation and a local residual.
    Linguistic features weakly modulate sink strength, rather than select its target.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
