    attention[0, 0] = 1.0

    for i in range(1, n):
        # Position zero remains dominant even far beyond the opening clause.
        sink = 0.975 - 0.22 * (1.0 - np.exp(-i / 24.0))

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.is_punct:
                sink -= 0.10 * (1.0 - np.exp(-i / 6.0))
            elif word.pos_ in ("NOUN", "PROPN", "PRON", "VERB", "AUX"):
                sink += 0.015
            elif word.pos_ in ("CCONJ", "SCONJ", "PART"):
                sink -= 0.035
        elif tokens[i].isspace() or tokens[i].strip("ĠĊ") == "":
            sink -= 0.06

        sink = float(np.clip(sink, 0.58, 0.995))

        # The unobserved residual is conservatively spread over recent tokens.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual += 0.15 / i
        residual /= residual.sum()

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "first_token_sink_with_local_residual", attention


