def prog_L33H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradual positional weakening.
    Residual attention favors recent context, with weak syntactic modulation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.62 + 0.38 * np.exp(-i / 23.0)
        word = doc[alignment[i][0]] if alignment[i] else None

        if word is not None:
            if word.pos_ in ("PRON", "DET", "AUX"):
                sink += 0.025
            elif word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink -= 0.015
            if word.is_punct and any(c in word.text for c in ".!?"):
                sink -= 0.06

        sink = np.clip(sink, 0.55, 0.998)
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 8.0)
        residual[-1] += 0.25

        if word is not None:
            for target in inverse[word.head.i]:
                if 1 <= target <= i:
                    residual[target - 1] += 0.35

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "first_token_sink_with_decay", attention


