def prog_L33H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, largely independent of linguistic content.
    Reserve a small residual mass for diffuse attention to other causal tokens.
    """
    tokens = tokenize(sentence, tokenizer)
